begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('20000000-0000-4000-8000-000000000001','lr2-fixture@paceon.example'),('20000000-0000-4000-8000-000000000002','lr2-other@paceon.example');
create temporary table video_fixture(k text primary key,v jsonb);
grant all on video_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
insert into video_fixture values('add','{"action":"VIDEO_ADD","requestId":"20000000-0000-4000-8000-000000000010","workspaceId":"20000000-0000-4000-8000-000000000011","videoId":"dQw4w9WgXcQ","startSeconds":5,"title":"Fixture video"}');
insert into video_fixture select 'added',learning_video_command(v) from video_fixture where k='add';
select is(learning_video_command((select v from video_fixture where k='add')),(select v from video_fixture where k='added'),'Video replay returns exact result');
select is(learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'workspaceId',gen_random_uuid()) from video_fixture where k='add'))->>'duplicate','true','Owner video deduplicates across workspace IDs');
select throws_ok($$select learning_video_command((select v||'{"extra":1}' from video_fixture where k='add'))$$,'P0001','LEARNING_INVALID','Video RPC rejects extra keys');
select throws_ok($$select learning_video_command((select v||'{"title":"changed"}' from video_fixture where k='add'))$$,'P0001','LEARNING_CONFLICT','Request ID payload conflict');
select throws_ok($$update learning_videos set favorite=true$$,'42501',null,'No direct video mutation');
select throws_ok($$delete from learning_video_notes$$,'42501',null,'No direct note mutation');
insert into video_fixture values('source',jsonb_build_object('action','VIDEO_SOURCE','requestId',gen_random_uuid(),'workspaceId','20000000-0000-4000-8000-000000000011','expectedVersion',0,'transcript','Source only evidence','contextStart',0,'contextEnd',20));
select lives_ok($$select learning_video_command((select v from video_fixture where k='source'))$$,'Transcript selected with CAS');
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='source'))$$,'P0001','LEARNING_CONFLICT','Stale transcript version rejected');
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'expectedVersion',1,'contextEnd',21) from video_fixture where k='source'))$$,'P0001','LEARNING_INVALID','Excerpt past transcript rejected');
insert into video_fixture select 'start',jsonb_build_object('action','START','requestId',gen_random_uuid(),'workspaceId','20000000-0000-4000-8000-000000000011','deviceId','20000000-0000-4000-8000-000000000012','timezone','UTC');
insert into video_fixture select 'session',learning_command(v)->'session' from video_fixture where k='start';
insert into video_fixture select 'tick',jsonb_build_object('action','VIDEO_TICK','requestId',gen_random_uuid(),'sessionId',v->>'id','deviceId',v->>'device_id','generation',(v->>'generation')::int,'positionSeconds',5,'durationSeconds',500,'playing',true,'rate',2) from video_fixture where k='session';
select lives_ok($$select learning_video_command((select v from video_fixture where k='tick'))$$,'Playing observation accepted');
reset role;
-- Simulate only these fixtures' server receipts; no sleep or real user mutation.
update learning_private.video_observations set observed_at=clock_timestamp()-interval '10 seconds' where session_id=(select (v->>'id')::uuid from video_fixture where k='session');
update learning_sessions set last_seen_at=clock_timestamp()-interval '10 seconds',last_activity_at=clock_timestamp()-interval '10 seconds' where user_id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',25) from video_fixture where k='tick'));
select is((select count(*) from learning_video_visits where user_id='20000000-0000-4000-8000-000000000001'),1::bigint,'2x playback records a plausible media segment');
select ok((select elapsed_seconds between 10 and 11 from learning_sessions where id=(select (v->>'id')::uuid from video_fixture where k='session')),'2x media credits ten wall seconds, not twenty');
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',200) from video_fixture where k='tick'));
select is((select count(*) from learning_video_visits where user_id='20000000-0000-4000-8000-000000000001'),1::bigint,'Seek jump is not a viewing segment');
select is((select position_seconds from learning_videos where workspace_id='20000000-0000-4000-8000-000000000011'),200::numeric,'Seek still updates resume position');
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',200,'playing',false) from video_fixture where k='tick'));
select is((select status from learning_sessions where id=(select (v->>'id')::uuid from video_fixture where k='session')),'PAUSED','Buffer or pause stops wall clock without writing');
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',200) from video_fixture where k='tick'));
select is((select status from learning_sessions where id=(select (v->>'id')::uuid from video_fixture where k='session')),'ACTIVE','Visible playback resumes idle timer');
insert into video_fixture select 'heartbeat', (v-array['positionSeconds','durationSeconds','playing','rate'])||jsonb_build_object('action','HEARTBEAT','requestId',gen_random_uuid(),'activity',true) from video_fixture where k='tick';
select learning_command((select v from video_fixture where k='heartbeat'));
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',200,'playing',false) from video_fixture where k='tick'));
select is((select status from learning_sessions where id=(select (v->>'id')::uuid from video_fixture where k='session')),'ACTIVE','Recent writing keeps the shared timer active while video pauses');
select learning_command((select v||jsonb_build_object('action','PAUSE','requestId',gen_random_uuid(),'reason','MANUAL') from video_fixture where k='heartbeat'));
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'positionSeconds',200) from video_fixture where k='tick'));
select is((select pause_reason from learning_sessions where id=(select (v->>'id')::uuid from video_fixture where k='session')),'MANUAL','Player cannot undo manual pause');
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'generation',99) from video_fixture where k='tick'))$$,'P0001','LEARNING_CONFLICT','Stale generation rejected');
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'deviceId',gen_random_uuid()) from video_fixture where k='tick'))$$,'P0001','LEARNING_CONFLICT','Wrong device rejected');
insert into video_fixture select 'summaryCommand',jsonb_build_object('action','SUMMARY','requestId',gen_random_uuid(),'workspaceId',v->>'workspace_id','sessionId',v->>'id') from video_fixture where k='session';
insert into video_fixture select 'summary',learning_command(v) from video_fixture where k='summaryCommand';
select is(learning_command((select v from video_fixture where k='summaryCommand')),(select v from video_fixture where k='summary'),'Source summary replay preserves LR1 idempotency');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select is((select count(*) from learning_videos),0::bigint,'Video RLS hides foreign videos');
select is((select count(*) from learning_video_visits),0::bigint,'Visit RLS hides foreign history');
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='tick'))$$,'P0001','LEARNING_NOT_FOUND','Foreign session hidden');
reset role;
select is((select input->'source'->>'transcript' from learning_ai_jobs where id=(select (v->'job'->>'id')::uuid from video_fixture where k='summary')),'Source only evidence','Worker input snapshots selected source');
select is((select input->'messages' from learning_ai_jobs where id=(select (v->'job'->>'id')::uuid from video_fixture where k='summary')),'[]'::jsonb,'Source summary never invents USER messages');
update learning_ai_jobs set status='SUCCEEDED' where id=(select (v->'job'->>'id')::uuid from video_fixture where k='summary');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select is(learning_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='summaryCommand'))->'job'->>'id',(select v->'job'->>'id' from video_fixture where k='summary'),'Unchanged source reuses completed summary');
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid(),'expectedVersion',1,'transcript','Changed source','contextEnd',14) from video_fixture where k='source'));
select isnt(learning_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='summaryCommand'))->'job'->>'id',(select v->'job'->>'id' from video_fixture where k='summary'),'Changed source does not reuse old summary');
reset role;
insert into learning_video_notes(id,workspace_id,user_id,position_seconds,content) select gen_random_uuid(),'20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000001',i,repeat('n',4000) from generate_series(1,6) i;
select throws_ok($$select learning_private.video_input('20000000-0000-4000-8000-000000000011','{"messages":[],"prompt":""}')$$,'P0001','LEARNING_LIMIT','Combined source context fails explicitly above 20000');
-- A source quote alone is not eligible for a correction, even through the worker RPC.
update learning_ai_jobs set status='RUNNING',lease_token='20000000-0000-4000-8000-000000000090',lease_expires_at=clock_timestamp()+interval '3 minutes'
where id=(select (v->'job'->>'id')::uuid from video_fixture where k='summary');
select throws_ok($$select finish_learning_job((select (v->'job'->>'id')::uuid from video_fixture where k='summary'),'20000000-0000-4000-8000-000000000090','{"summary":"A source summary","corrections":[{"original":"Source only evidence","revised":"Changed","reason":"Not user writing"}],"expressions":[],"nextPrompt":""}',null,'fixture',null,1,1)$$,'P0001','LEARNING_INVALID','Source quotes cannot be correction originals');
delete from learning_video_notes where user_id='20000000-0000-4000-8000-000000000001';
insert into learning_video_notes(id,workspace_id,user_id,position_seconds,content) select gen_random_uuid(),'20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000001',i,'Note '||i from generate_series(1,25) i;
select is(jsonb_array_length(learning_private.video_input('20000000-0000-4000-8000-000000000011','{"messages":[],"prompt":""}')->'source'->'notes'),20,'Snapshot notes bounded to latest twenty');
update learning_sessions set status='ACTIVE',pause_reason=null,lease_expires_at=clock_timestamp()-interval '1 second' where id=(select (v->>'id')::uuid from video_fixture where k='session');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
select throws_ok($$select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='tick'))$$,'P0001','LEARNING_CONFLICT','Expired live lease cannot extend viewing');
reset role;
-- Empty/whitespace source evidence must fail before spending a summary request.
delete from learning_video_notes where user_id='20000000-0000-4000-8000-000000000001';
update learning_videos set transcript=E' \n\t\r ',context_start=0,context_end=5 where workspace_id='20000000-0000-4000-8000-000000000011';
select throws_ok($$select learning_private.video_input('20000000-0000-4000-8000-000000000011','{"kind":"STUDY_SUMMARY","messages":[],"prompt":""}')$$,'P0001','LEARNING_INVALID','Whitespace-only source cannot queue summary');
update learning_videos set transcript=chr(160)||chr(8195)||chr(12288),context_end=3 where workspace_id='20000000-0000-4000-8000-000000000011';
select throws_ok($$select learning_private.video_input('20000000-0000-4000-8000-000000000011','{"kind":"STUDY_SUMMARY","messages":[],"prompt":""}')$$,'P0001','LEARNING_INVALID','Unicode whitespace admission matches Python strip');
update learning_videos set transcript='Unselected source',context_end=0 where workspace_id='20000000-0000-4000-8000-000000000011';
select throws_ok($$select learning_private.video_input('20000000-0000-4000-8000-000000000011','{"kind":"STUDY_SUMMARY","messages":[],"prompt":""}')$$,'P0001','LEARNING_INVALID','Empty selected excerpt cannot queue summary');
insert into video_fixture select 'quotaBefore',to_jsonb(count(*)) from learning_private.job_requests where user_id='20000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select learning_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='summaryCommand'))$$,'P0001','LEARNING_INVALID','Summary boundary rejects missing source before queue checks');
reset role;
select is((select count(*) from learning_private.job_requests where user_id='20000000-0000-4000-8000-000000000001'),(select v::text::bigint from video_fixture where k='quotaBefore'),'Invalid source does not consume summary quota');
insert into learning_video_notes(id,workspace_id,user_id,position_seconds,content) values(gen_random_uuid(),'20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000001',0,'Meaningful note');
select lives_ok($$select learning_private.video_input('20000000-0000-4000-8000-000000000011','{"kind":"STUDY_SUMMARY","messages":[],"prompt":""}')$$,'Nonblank notes alone remain valid summary evidence');
-- Video-only activity must move its workspace in the shared recent list.
update learning_workspaces set draft='Preserve this draft.',updated_at='2000-01-01' where id='20000000-0000-4000-8000-000000000011';
set local role authenticated;
select learning_video_command(jsonb_build_object('action','VIDEO_SOURCE','requestId',gen_random_uuid(),'workspaceId','20000000-0000-4000-8000-000000000011','expectedVersion',(select transcript_version from learning_videos where workspace_id='20000000-0000-4000-8000-000000000011'),'transcript','Recent source','contextStart',0,'contextEnd',13));
select is((select updated_at from learning_workspaces where id='20000000-0000-4000-8000-000000000011'),(select updated_at from learning_videos where workspace_id='20000000-0000-4000-8000-000000000011'),'Source save updates shared workspace recency');
reset role;
update learning_workspaces set updated_at='2000-01-01' where id='20000000-0000-4000-8000-000000000011';
update learning_sessions set status='PAUSED',pause_reason='IDLE',last_seen_at=clock_timestamp() where id=(select (v->>'id')::uuid from video_fixture where k='session');
set local role authenticated;
select learning_video_command((select v||jsonb_build_object('requestId',gen_random_uuid()) from video_fixture where k='tick'));
select is((select updated_at from learning_workspaces where id='20000000-0000-4000-8000-000000000011'),(select updated_at from learning_videos where workspace_id='20000000-0000-4000-8000-000000000011'),'Playback updates shared workspace recency');
select is((select title from learning_workspaces where id='20000000-0000-4000-8000-000000000011'),'Fixture video','Video recency preserves user title');
select is((select draft from learning_workspaces where id='20000000-0000-4000-8000-000000000011'),'Preserve this draft.','Video recency preserves writing draft');
reset role;
select * from finish();
rollback;
